<section class="dashboard-hero"><div><p class="eyebrow"><?=\App\Core\Authorization::isRegistrar()?'Registrar workspace':'School overview'?></p><h1>Welcome back, <?=e($user['display_name'])?></h1><p><?=e(date('l, F j, Y'))?> · Here is what needs your attention.</p></div><div class="hero-actions"><?php if(\App\Core\Authorization::allows('students.create')):?><a class="button primary" href="<?=e(url('/students/create'))?>">+ Add student</a><?php endif;?><?php if(\App\Core\Authorization::allows('students.import')):?><a class="button" href="<?=e(url('/students/import'))?>">Import CSV</a><?php elseif(\App\Core\Authorization::allows('events.view')):?><a class="button" href="<?=e(url('/events'))?>">View calendar</a><?php endif;?></div></section>
<?php if(\App\Core\Authorization::isRegistrar()):?>
<div class="grid four dashboard-stats"><article class="stat-card"><span>Currently enrolled</span><strong><?=$summary['enrolled_students']?></strong><small>Active students with current enrollment</small></article><article class="stat-card"><span>Needs enrollment</span><strong><?=$summary['students_without_enrollment']?></strong><small>Active students without a section</small></article><article class="stat-card"><span>Incomplete profiles</span><strong><?=$summary['incomplete_student_profiles']?></strong><small>Missing essential student information</small></article><article class="stat-card"><span>Transferred / withdrawn</span><strong><?=$summary['transfers_withdrawals']?></strong><small>Records requiring retention</small></article></div>
<?php else:?>
<div class="grid four dashboard-stats"><article class="stat-card"><span>Active students</span><strong><?=$summary['students']?></strong><small>Current student profiles</small></article><article class="stat-card"><span>Active teachers</span><strong><?=$summary['teachers']?></strong><small>Current faculty profiles</small></article><article class="stat-card"><span>Absent today</span><strong><?=$summary['student_absences']+$summary['teacher_absences']?></strong><small><?=$summary['student_absences']?> students · <?=$summary['teacher_absences']?> teachers</small></article><article class="stat-card"><span>Upcoming events</span><strong><?=$summary['upcoming_events']?></strong><small>Published activities</small></article></div>
<?php endif;?>
<?php if($summary['insurance_expiring']>0&&\App\Core\Authorization::allows('insurance.view')):?><div class="alert danger"><strong>Insurance attention:</strong> <?=$summary['insurance_expiring']?> active <?= $summary['insurance_expiring']===1?'policy expires':'policies expire' ?> within 30 days. <a href="<?=e(url('/insurance?status=active'))?>">Review coverage</a>.</div><?php endif;?>
<div class="dashboard-panels"><section class="card section-card"><div class="page-heading compact"><div><p class="eyebrow">Schedule</p><h2>Upcoming events</h2></div><?php if(\App\Core\Authorization::allows('events.view')):?><a class="button small" href="<?=e(url('/events'))?>">View all</a><?php endif;?></div><?php foreach($upcoming as $event):?><p><strong><a href="<?=e(url('/events/'.$event['id']))?>"><?=e($event['title'])?></a></strong><br><small><?=e(date('M j, Y g:i A',strtotime($event['starts_at'])))?> · <?=e($event['venue']?:'Venue not set')?></small></p><?php endforeach;?><?php if(!$upcoming):?><p class="empty">No published upcoming events.</p><?php endif;?></section><section class="card section-card"><div class="page-heading compact"><div><p class="eyebrow">Bulletin</p><h2>Announcements</h2></div><?php if(\App\Core\Authorization::allows('settings.view')):?><a class="button small" href="<?=e(url('/admin/settings'))?>">Manage</a><?php endif;?></div><?php foreach($announcements as $a):?><article class="announcement"><span class="badge"><?=e($a['audience'])?></span><h3><?=e($a['title'])?></h3><p><?=nl2br(e($a['body']))?></p><small><?=e($a['published_at'])?></small></article><?php endforeach;?><?php if(!$announcements):?><p class="empty">No current announcements.</p><?php endif;?></section></div>
<?php if(\App\Core\Authorization::allows('students.view')&&\App\Core\Authorization::allows('teachers.view')):?><section class="card section-card birthday-section"><div class="page-heading compact"><div><p class="eyebrow">Community</p><h2><?=e(date('F'))?> birthday celebrants</h2><p>Active students and teachers celebrating this month.</p></div><span class="birthday-count"><?=count($birthdays)?> celebrants</span></div><div class="birthday-grid"><?php foreach($birthdays as $person):?><?php $today=(int)date('j');$day=(int)$person['birthday_day'];$timing=$day===$today?'Today':($day>$today?'Upcoming':'Celebrated');?><a class="birthday-card" href="<?=e(url('/'.($person['person_type']==='student'?'students':'teachers').'/'.$person['id']))?>"><span class="birthday-date"><strong><?=e(date('d',strtotime($person['birth_date'])))?></strong><small><?=e(date('M',strtotime($person['birth_date'])))?></small></span><span class="birthday-person"><strong><?=e($person['first_name'].' '.$person['last_name'])?></strong><small><?=e(ucfirst($person['person_type']).' · '.$person['reference_no'].' · Turns '.$person['turning_age'])?></small></span><span class="birthday-timing <?=$timing==='Today'?'today':''?>"><?=e($timing)?></span></a><?php endforeach;?><?php if(!$birthdays):?><div class="empty birthday-empty"><span>✦</span><p>No active student or teacher birthdays recorded for <?=e(date('F'))?>.</p></div><?php endif;?></div></section><?php endif;?>
